    /// How many records `bytes` holds, by one pass over them.
    pub fn count(bytes: impl Read, format: Format) -> Result<usize>;

    impl<R: Read> Reader<R> {
        /// The global index of the current record.
        pub fn position(&self) -> usize;

        /// Advance until the record at `n` is current. `n` must be at or after
        /// the current position, since a Reader cannot go back.
        pub fn advance_to(&mut self, n: usize) -> Result<bool>;
    }

Which collapses pass 2 to:

    let mut reader = Reader::new(File::open(path)?, format);

    for n in Selection::new(count, m, seed) {
        if !reader.advance_to(n)? { break; }
        take(reader.record());
    }

advance_to is where a caller with an index would seek instead of scan, so the decision stays where it was.

count takes one source and not a chained one, deliberately: see the multi-source reader issue for why Read::chain loses records.
